with base as (select id, name, country, segment, signup_date, credit_limit, age, round(credit_limit / age, 2) as credit_limit_per_age from customers where signup_date > date '2023-03-08'), deduped as (select * from base qualify row_number() over (partition by segment, country order by signup_date nulls first, id) = 1), scored as (select id, country, segment, credit_limit, age, credit_limit_per_age, avg(credit_limit_per_age) over (partition by segment) as segment_avg_credit_limit_per_age, ntile(10) over (partition by country order by credit_limit desc, id) as credit_limit_bucket, avg(credit_limit_per_age) over (partition by country, segment order by credit_limit_per_age, id rows between 2 preceding and current row) as credit_limit_per_age_avg_2 from deduped where segment not in ('SMB', 'Consumer')), cleaned as (select id, segment, credit_limit, age, segment_avg_credit_limit_per_age, credit_limit_bucket, credit_limit_per_age_avg_2, greatest(age, credit_limit_bucket) as greatest_age_credit_limit_bucket from scored where segment is not null) select id, segment, credit_limit, segment_avg_credit_limit_per_age, credit_limit_per_age_avg_2, greatest_age_credit_limit_bucket, case when segment rlike '^(Corporate|SMB)$' then 'GROUP_A' else 'PRIORITY' end as segment_zone from cleaned order by id, credit_limit limit 10
